<template>
  <section ref="panel" class="memory-panel" role="dialog" aria-modal="true" aria-labelledby="memory-title" @keydown.esc.stop.prevent="$emit('close')" @keydown.tab="trap">
    <header><div class="header-mark" aria-hidden="true">✧</div><div class="header-copy"><span class="eyebrow">属于你的助手</span><h2 id="memory-title">记忆管理</h2><p>记住重要的小事，也把决定权留给你。</p></div><button ref="closeButton" class="close-button" type="button" aria-label="关闭记忆管理" @click="$emit('close')">×</button></header>
    <div class="memory-body" :aria-busy="busy">
      <div v-if="notice" class="memory-notice" :class="{error:noticeError}" :role="noticeError ? 'alert' : 'status'">{{ notice }}<button v-if="noticeError" type="button" :disabled="busy" @click="load">重新加载</button></div>
      <div v-if="!user.isLogin" class="memory-empty"><span aria-hidden="true">✧</span><h3>登录后，记忆才有自己的归处</h3><p>登录后可以查看、添加和管理你的记忆。</p></div>
      <template v-else-if="settings">
        <section class="settings-card" aria-label="记忆设置">
          <div class="section-heading"><h3>记忆如何帮你</h3><span class="state-badge" :class="{muted:settings.mode==='OFF'}">{{ modeLabels[settings.mode] }}</span></div>
          <div class="mode-options" role="group" aria-label="助手记忆模式"><button v-for="option in modes" :key="option.value" type="button" :class="{selected:settings.mode===option.value}" :aria-pressed="settings.mode===option.value" :disabled="busy" @click="mode(option.value)"><strong>{{ option.label }}</strong><small>{{ option.description }}</small></button></div>
          <div class="automatic-row"><div><h4>自动整理对话</h4><p>{{ settings.mode!=='ON' ? '当前模式下暂不整理；切回使用并保存后，按原设置恢复。' : settings.autoExtract ? '在后台挑选值得长期保留的信息，不打断聊天。' : '不自动整理普通聊天；明确说“请记住”仍可保存。' }}</p></div><button type="button" role="switch" :aria-checked="settings.autoExtract" aria-label="自动整理对话" class="memory-switch" :class="{checked:settings.autoExtract}" :disabled="busy || settings.mode!=='ON'" @click="automatic(!settings.autoExtract)"><span /></button></div>
          <p class="settings-note">暂停后，已有记录仍可在这里查看和删除。关闭自动整理不会清空记忆。</p>
        </section>
        <section class="saved-section" aria-label="已保存的记忆">
          <div class="section-heading"><div><h3>已保存的记忆 <span class="item-count">{{ items.length }}{{ nextBefore ? '+' : '' }}</span></h3><p class="section-note">只有你认可的信息，才值得留下。</p></div><button ref="addButton" type="button" class="primary" :disabled="busy || settings.mode!=='ON'" @click="newMemory">＋ 添加</button></div>
          <form class="memory-filters" role="search" @submit.prevent="refresh"><label><span class="sr-only">记忆范围</span><select v-model="scopeType" :disabled="busy" @change="changeScope"><option value="USER">个人记忆</option><option v-if="videoId" value="VIDEO">当前视频</option><option v-for="topic in topics" :key="topic.id" :value="topic.id">{{ topic.name }}</option></select></label><input v-model="query" aria-label="搜索记忆内容" placeholder="找一条记忆…" maxlength="128" :disabled="busy"><button type="submit" :disabled="busy">查找</button></form>
          <form v-if="editorOpen" class="memory-editor" @submit.prevent="save"><div class="section-heading"><h4>{{ editing ? '修改这条记忆' : '添加一条记忆' }}</h4><button type="button" class="text-button" :disabled="busy" @click="cancelEdit">取消</button></div><label><span class="sr-only">记忆内容</span><textarea ref="editorInput" v-model="text" rows="4" maxlength="1024" placeholder="例如：解释概念时，我喜欢先看一个简单例子。" :disabled="busy || settings.mode!=='ON'" /></label><p class="editor-hint" :class="{error:textTooLong}">{{ textTooLong ? '这条记忆有点长，请缩短后再保存。' : '写清一个事实、一种偏好，或一个持续目标就好。' }}</p><div class="editor-actions"><select v-model="kind" aria-label="记忆类型" :disabled="busy"><option v-for="(label,value) in kindNames" :key="value" :value="value">{{ label }}</option></select><button type="submit" class="primary" :disabled="busy || !text.trim() || textTooLong || settings.mode!=='ON'">{{ busy ? '保存中…' : editing ? '保存修改' : '保存记忆' }}</button></div></form>
          <div v-if="busy && !items.length" class="memory-empty" role="status">正在读取你的记忆…</div>
          <div v-else-if="!items.length" class="memory-empty"><span aria-hidden="true">✧</span><h4>{{ query ? '暂时没有找到这条记忆' : '留一点空间给重要的事' }}</h4><p>{{ query ? '换个关键词试试，或清空搜索查看已有记录。' : '你可以主动添加，也可以在聊天时说“请记住”。' }}</p><button v-if="query" type="button" :disabled="busy" @click="clearSearch">查看全部</button></div>
          <div v-else class="memory-list"><article v-for="item in items" :key="item.id" class="memory-item" :class="{editing:editing?.id===item.id}"><div class="memory-item-meta"><span class="kind-badge" :data-kind="item.content.kind">{{ kindNames[item.content.kind] || '其他记录' }}</span><time :datetime="item.createdAt">{{ formatDate(item.createdAt) }}</time></div><p class="memory-content">{{ item.content.text }}</p><div v-if="forgetting===item.id" class="forget-confirm"><p>忘记后，助手将不再使用这条记录。</p><div><button type="button" class="danger" :disabled="busy" @click="forget(item)">确认忘记</button><button type="button" :disabled="busy" @click="forgetting=null">保留</button></div></div><div v-else class="memory-item-actions"><button type="button" class="text-button" :disabled="busy || settings.mode!=='ON'" @click="edit(item)">修改</button><button type="button" class="text-button danger-text" :disabled="busy" @click="forgetting=item.id">忘记</button></div></article></div>
          <button v-if="nextBefore" type="button" class="more-button" :disabled="busy" @click="more">{{ busy ? '正在读取…' : '查看更早的记忆 ↓' }}</button>
        </section>
        <footer><div><h4>清空全部记忆</h4><p>包含所有范围的记录；聊天记录本身不会被删除。</p></div><button v-if="!resetConfirm" type="button" class="text-button danger-text" :disabled="busy" @click="resetConfirm=true">清空…</button><div v-else class="reset-confirm"><p>确认忘记全部记录？旧聊天不会自动重新生成这些记忆。</p><div><button type="button" class="danger" :disabled="busy" @click="reset">确认清空</button><button type="button" :disabled="busy" @click="resetConfirm=false">取消</button></div></div></footer>
      </template>
      <p v-else-if="busy" class="memory-empty" role="status">正在读取你的记忆…</p>
    </div>
  </section>
</template>

<script setup>
import { ref, computed, nextTick, watch, onMounted, onBeforeUnmount } from 'vue'
import { useUserStore } from '@/store/user'
import { memoryRequest } from '@/api/agent'
import { onMemoryChanged } from '@/lib/memory-events.mjs'
const props=defineProps({videoId:{type:String,default:''}})
defineEmits(['close'])
const user=useUserStore(), panel=ref(null), closeButton=ref(null), addButton=ref(null), editorInput=ref(null)
const settings=ref(null), topics=ref([]), items=ref([]), busy=ref(false), notice=ref(''), noticeError=ref(false), scopeType=ref('USER'), query=ref(''), nextBefore=ref(0)
const text=ref(''), kind=ref('PREFERENCE'), editing=ref(null), resetConfirm=ref(false), editorOpen=ref(false), forgetting=ref(null)
const kindNames={PREFERENCE:'偏好',GOAL:'持续目标',PROFILE:'个人事实',EPISODE:'历史经历',EXPERIENCE:'经验',SESSION_SUMMARY:'会话摘要'}
const modes=[{value:'ON',label:'使用并保存',description:'让记忆帮助之后的回答'},{value:'READ_ONLY',label:'只使用',description:'使用已有记录，暂不新增'},{value:'OFF',label:'暂停',description:'暂不使用，也不保存'}]
const modeLabels={ON:'记忆已开启',READ_ONLY:'仅使用已有记录',OFF:'记忆已暂停'}
const textTooLong=computed(()=>new TextEncoder().encode(text.value.trim()).length>1024)
const formatDate=value=>{const d=new Date(value);return Number.isNaN(d.getTime())?'':d.toLocaleDateString('zh-CN',{month:'long',day:'numeric'})}
let previousFocus=null
let generation=0, controller=new AbortController(), pending=null
const stopMemoryChanges=onMemoryChanged(source=>{if(source==='local')return;generation++;controller.abort();controller=new AbortController();items.value=[];nextBefore.value=0;busy.value=false;forgetting.value=null;resetConfirm.value=false;if(user.isLogin)load()})
const scope=()=>scopeType.value==='USER'?{type:'USER',key:'self'}:scopeType.value==='VIDEO'?{type:'VIDEO',key:props.videoId}:{type:'TOPIC',key:scopeType.value}
const request=(path,options={})=>memoryRequest(path,{...options,signal:controller.signal})
function key(signature){if(pending?.signature!==signature)pending={signature,key:crypto.randomUUID()};return pending.key}
async function act(operation){if(busy.value || !user.isLogin)return;busy.value=true;notice.value='';noticeError.value=false;const current=generation;try{await operation(current)}catch(e){if(current===generation && e.name!=='AbortError'){noticeError.value=true;notice.value=e.status===404?'记忆服务暂时不可用，请稍后再试。':e.code==='MEMORY_VERSION_CONFLICT'?'记录已经变化，请取消编辑并重新打开最新记录；当前填写的内容仍保留。':e.message || '暂时没有完成，请重试。'}}finally{if(current===generation)busy.value=false}}
async function list(before=Number.MAX_SAFE_INTEGER,append=false,current=generation){const target=scope();const result=await request('/memories?'+new URLSearchParams({scopeType:target.type,scopeKey:target.key,limit:'20',beforeSequence:String(before),query:query.value}));if(current!==generation)return;items.value=append?[...new Map([...items.value,...result.items].map(x=>[x.id,x])).values()]:result.items;nextBefore.value=result.moreAvailable?result.nextBeforeSequence:0}
async function load(){await act(async current=>{const [state,groups]=await Promise.all([request('/memory-settings'),request('/memory-topics')]);if(current!==generation)return;settings.value=state;topics.value=groups;await list(undefined,false,current)})}
const refresh=()=>act(current=>list(undefined,false,current))
const more=()=>act(current=>list(nextBefore.value,true,current))
function cancelEdit(){editing.value=null;text.value='';kind.value='PREFERENCE';editorOpen.value=false;pending=null}
async function newMemory(){cancelEdit();editorOpen.value=true;await nextTick();editorInput.value?.focus()}
function clearSearch(){query.value='';refresh()}
async function edit(item){editing.value=item;text.value=item.content.text;kind.value=item.content.kind;editorOpen.value=true;forgetting.value=null;pending=null;await nextTick();editorInput.value?.focus();editorInput.value?.scrollIntoView({block:'nearest'})}
function changeScope(){cancelEdit();forgetting.value=null;refresh()}
async function save(){if(textTooLong.value || !text.value.trim())return;await act(async current=>{const body={expectedVersion:editing.value?.version || 0,content:{scope:scope(),kind:kind.value,text:text.value}};const path='/memories'+(editing.value?'/'+editing.value.id:'');const signature=path+JSON.stringify(body);await request(path,{method:editing.value?'PATCH':'POST',headers:{'Idempotency-Key':key(signature)},body:JSON.stringify(body)});if(current!==generation)return;cancelEdit();notice.value='已保存，下次对话就可以用上。';await list(undefined,false,current)})}
async function forget(item){await act(async current=>{const path=`/memories/${item.id}?expectedVersion=${item.version}`;await request(path,{method:'DELETE',headers:{'Idempotency-Key':key(path)}});if(current!==generation)return;pending=null;forgetting.value=null;if(editing.value?.id===item.id)cancelEdit();notice.value='已忘记。';await list(undefined,false,current)})}
async function mode(value){if(value===settings.value.mode)return;await act(async current=>{const result=await request('/memory-settings',{method:'PATCH',body:JSON.stringify({expectedVersion:settings.value.version,mode:value})});if(current===generation)settings.value=result})}
async function automatic(value){await act(async current=>{const result=await request('/memory-settings/automatic',{method:'PUT',body:JSON.stringify({expectedVersion:settings.value.version,enabled:value})});if(current===generation)settings.value=result})}
async function reset(){await act(async current=>{await request('/memories/reset',{method:'POST',headers:{'Idempotency-Key':key('reset:'+settings.value.sequence+':'+settings.value.eraseEpoch)}});if(current!==generation)return;pending=null;resetConfirm.value=false;forgetting.value=null;cancelEdit();notice.value='已清空全部记忆。';await list(undefined,false,current)})}
function trap(event){const controls=[...panel.value.querySelectorAll('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),select:not(:disabled)')];const first=controls[0],last=controls.at(-1);if(event.shiftKey && document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey && document.activeElement===last){event.preventDefault();first?.focus()}}
watch(()=>user.user?.token,()=>{generation++;controller.abort();controller=new AbortController();items.value=[];topics.value=[];settings.value=null;busy.value=false;notice.value='';forgetting.value=null;resetConfirm.value=false;cancelEdit();if(user.isLogin)load()})
watch(()=>props.videoId,()=>{if(scopeType.value==='VIDEO'){generation++;controller.abort();controller=new AbortController();busy.value=false;items.value=[];forgetting.value=null;cancelEdit();if(!props.videoId)scopeType.value='USER';refresh()}})
onMounted(()=>{previousFocus=document.activeElement;closeButton.value?.focus();if(user.isLogin)load()})
onBeforeUnmount(()=>{stopMemoryChanges();generation++;controller.abort();if(previousFocus?.isConnected)previousFocus.focus()})
</script>

<style scoped>
.memory-panel{position:absolute;inset:62px 12px 12px;z-index:45;display:flex;flex-direction:column;background:#faf9f5;color:#242722;border:1px solid #e8e6dc;border-radius:20px;box-shadow:0 12px 40px #24272212;font-family:inherit;text-align:left;overflow:hidden}
.memory-panel header{display:flex;gap:14px;align-items:flex-start;padding:24px;border-bottom:1px solid #e8e6dc}.header-mark{display:grid;place-items:center;flex:none;width:44px;height:44px;border-radius:14px;background:#f3e2d7;color:#b65b3d;font-size:29px}.header-copy{flex:1;min-width:0}.eyebrow{font-size:11px;color:#85847b;letter-spacing:.08em}.memory-panel h2{font-size:23px;line-height:1.35;font-weight:600;letter-spacing:-.03em;margin:3px 0 0}.memory-panel h3{margin:0;font-size:15px;font-weight:600}.memory-panel h4{margin:0;font-size:13px;font-weight:550}.memory-panel p{line-height:1.65;margin:6px 0}.header-copy p{font-size:12px;color:#787a70;margin-bottom:0}.memory-body{padding:22px 24px 8px;overflow:auto;flex:1;min-height:0;scrollbar-width:thin;scrollbar-color:#d1cfc5 transparent}
.memory-panel button{display:inline-flex;align-items:center;justify-content:center;min-height:34px;border:1px solid #deddd3;border-radius:9px;padding:7px 12px;background:#faf9f5;color:#595d52;cursor:pointer;font:inherit;font-size:12px;transition:background .15s,border-color .15s}.memory-panel button:hover{background:#f0efe7;border-color:#c9c7bb}.memory-panel button:disabled{opacity:.48;cursor:not-allowed}.memory-panel .close-button{border:0;flex:none;min-height:30px;width:30px;padding:0;font-size:24px;color:#85847b}.memory-panel .text-button{border:0;background:transparent;padding:5px 8px}.memory-panel .primary{background:#c96442;border-color:#c96442;color:#fffaf5}.memory-panel .primary:hover{background:#b85b3b}.memory-panel .danger-text{color:#a0644f}.memory-panel .danger{color:#a64c36;background:#f4e7de;border-color:#ebd3c4}.memory-panel :focus-visible{outline:2px solid #c96442;outline-offset:3px}
.section-heading{display:flex;justify-content:space-between;align-items:center;gap:12px}.settings-card{background:#f3f2eb;border:1px solid #e8e6dc;border-radius:14px;padding:16px}.state-badge,.kind-badge{display:inline-flex;align-items:center;white-space:nowrap;border-radius:6px;padding:3px 7px;font-size:10px;line-height:1.5;color:#587050;background:#e6ecdf}.state-badge.muted{background:#e8e6dc;color:#85847b}.mode-options{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin-top:14px}.memory-panel .mode-options button{display:flex;flex-direction:column;align-items:flex-start;gap:3px;text-align:left;padding:10px 9px;background:#faf9f5;border-color:#e5e3d9}.mode-options strong{font-size:12px;font-weight:500}.mode-options small{font-size:10px;line-height:1.5;color:#85847b}.memory-panel .mode-options .selected{background:#f3e2d7;border-color:#d8ae94;color:#975537}.mode-options .selected small{color:#a56c50}.automatic-row{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-top:17px;padding-top:15px;border-top:1px solid #e3e1d7}.automatic-row p{font-size:11px;color:#787a70;margin-bottom:0}.memory-panel .memory-switch{width:35px;min-height:21px;height:21px;flex:none;padding:2px;border:0;border-radius:99px;background:#d1cfc5;justify-content:flex-start}.memory-switch span{display:block;width:17px;height:17px;border-radius:50%;background:#fffefa;box-shadow:0 1px 3px #24272220;transition:transform .15s}.memory-panel .memory-switch.checked{background:#718269}.memory-switch.checked span{transform:translateX(14px)}.settings-note{font-size:10px;color:#85847b;margin-top:13px!important}
.saved-section{margin-top:25px}.section-note{font-size:11px;color:#85847b}.item-count{font-size:11px;font-weight:400;color:#85847b;margin-left:5px}.memory-filters{display:flex;gap:8px;margin:15px 0}.memory-panel select,.memory-panel input,.memory-panel textarea{box-sizing:border-box;border:1px solid #deddd3;background:#faf9f5;border-radius:9px;color:#42473e;font:inherit;font-size:12px;padding:9px 10px;max-width:100%}.memory-filters label{flex:0 1 125px;min-width:0}.memory-filters select{width:100%}.memory-filters input{flex:1;min-width:0}.memory-panel input::placeholder,.memory-panel textarea::placeholder{color:#96978c}
.memory-list{display:grid;gap:10px}.memory-item{border:1px solid #e8e6dc;background:#fffefa;border-radius:12px;padding:14px 15px}.memory-item.editing{border-color:#d8ae94}.memory-item-meta{display:flex;gap:10px;justify-content:space-between;align-items:center}.memory-item-meta time{font-size:10px;color:#96978c}.kind-badge{background:#eeede6;color:#77786c}.kind-badge[data-kind=PREFERENCE]{background:#f3e5d9;color:#9a6645}.kind-badge[data-kind=GOAL]{background:#e6ecdf;color:#63775a}.memory-panel .memory-content{font-size:13px;color:#42473e;line-height:1.8;margin:11px 0 4px;white-space:pre-wrap;overflow-wrap:anywhere}.memory-item-actions{display:flex;justify-content:flex-end;gap:8px}.memory-item-actions button{font-size:11px;min-height:28px}.forget-confirm{background:#f6eee6;border-radius:8px;padding:9px 11px;margin-top:10px}.forget-confirm p,.reset-confirm p{font-size:11px;color:#92664f}.forget-confirm>div,.reset-confirm>div{display:flex;justify-content:flex-end;gap:6px}
.memory-editor{border:1px solid #dfc5b2;background:#f6f0e7;border-radius:12px;padding:14px;margin:12px 0}.memory-panel textarea{display:block;width:100%;resize:vertical;line-height:1.7;margin-top:10px;background:#fffefa}.editor-hint{font-size:10px;color:#85847b}.editor-actions{display:flex;justify-content:space-between;gap:8px;margin-top:10px}.editor-actions select{min-height:34px;padding:6px 8px}.memory-panel .error{color:#a64c36}.memory-empty{padding:28px 16px;text-align:center;color:#85847b}.memory-empty>span{font-size:28px;color:#b6b9a7}.memory-empty h3,.memory-empty h4{margin-top:9px;color:#666c5d}.memory-empty p{font-size:12px}.memory-panel .more-button{width:100%;margin-top:13px;background:transparent;border-style:dashed}.memory-panel footer{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px;border-top:1px solid #e8e6dc;padding:18px 0;margin-top:24px}.memory-panel footer h4{color:#77786c;font-size:12px}.memory-panel footer p{font-size:10px;color:#96978c}.reset-confirm{flex-basis:100%;border-radius:10px;background:#f4e7de;padding:12px}.memory-notice{display:flex;gap:8px;align-items:center;justify-content:space-between;margin-bottom:15px;padding:10px 12px;border-radius:10px;background:#e9eee2;color:#63775a;font-size:12px;line-height:1.6}.memory-notice.error{background:#f4e7de}.memory-notice button{flex:none}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@media(max-width:480px){.memory-panel{inset:58px 6px 6px;border-radius:15px}.memory-panel header{padding:18px 16px;gap:10px}.header-mark{width:36px;height:36px;font-size:25px;border-radius:11px}.memory-body{padding:17px 14px 4px}.memory-panel h2{font-size:21px}.settings-card{padding:13px}.mode-options{gap:4px}.mode-options small{font-size:10px}.memory-panel .mode-options button{padding:9px 7px}.memory-filters{gap:6px}.memory-filters label{flex-basis:106px}.memory-item{padding:13px}.state-badge{font-size:9px}}
@media(prefers-reduced-motion:reduce){.memory-panel *{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
</style>
